(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["gv"] = {"ui":{"skip":"Lhie dys y chooid","back":"← Shaghey back gys AI-gile","lang.button":"Chengey: {name}","lang.dialog":"Reih chengey","lang.search":"Shirrey chengaghyn","lang.none":"Cha vel chengey erbee cheet cooidjagh","lang.notYet":"Cha vel {name} jarroodit foast","theme.aria":"Caghlaa y chummey: soilshey, dorraghey ny doo","theme.toLight":"Gow rish y chummey soilshey","theme.toDark":"Gow rish y chummey dorraghey","theme.toBlack":"Gow rish y chummey doo (doo firrinagh, aashagh er screenyn OLED)","words.underline":"Cur linney fo ny fockleyn shoh er y duillag","words.underlineHelp":"Cur y lugh er fockle lesh poyntyn fo, ny bean da, dy akin cre ta shen dy ghra.","index.title":"AI-gile: dty phossan AI, er un bord","index.description":"Ta AI-gile bord kanban son possanyn coadaghey AI. T'ad obbraghey choud as t'ou 'sy ruggyr; t'ou geddyn un chrink veg jeh reddyn dy hoiggal, dy hoiaghey as dy ghoaill rish.","hero.logoAlt":"Ard-ikon bord AI-gile","hero.h1.html":"Dty phossan AI, er un&nbsp;bord.","hero.alpha":"🐣 Roie-alpha dooint","hero.alphaTitle":"Toshiagh as neu-hie: gura mie ayd son y hoiaghey!","hero.lede":"T'ad troggal choud as t'ou 'sy ruggyr. T'ou dooyrt lesh un chrink veg: paartey dy ghoghyn, paartey dy reddyn dy hoiaghey, jeh diamond ghoair ny daa. Cliklee, gow rish, as ass lesh dty chaffee.","dl.windows":"Appey Windows","dl.browser":"Roie eh 'sy vrawseyr ayd","dl.messenger":"📱 Messenger son dty fone","dl.soon":"Tar dy gerrid","dl.notify":"🔔 Insh dou tra vees eh foshlit","dl.notifySmall":"Alpha ny beta","hero.secondary":"Agile, agh cha vel feme ec y phossan er caffee 'sy stadjey. (Ta'd jannoo ny stand-ups ny lomarcan.)","pitch.h2":"AI-gile ayns cha mennick focklyn as te baare lhiat","pitch.lede":"Reih lhiurid, veih un ockle gys 144. Ta gagh lhiurid e ard-ghoo hene, screeuit son yn eaghtyr shen. Tayrn y slider ny ymmyd ny kay-keayn.","pitch.rangeLabel":"Lhiurid ayns focklyn","pitch.dice":"🎲 lane elley","pitch.words.one":"{n} fockle","pitch.words.other":"{n} fockle","pitch.letters.one":"{n} lettyr","pitch.letters.other":"{n} lettyr","pitch.chars.one":"{n} caractar","pitch.chars.other":"{n} caractar","count.line.html.one":"{n} chart er y bord nish","count.line.html.other":"{n} chart er y bord nish","features.aria":"Cre ta eh jannoo","f.pile.h":"Un chrink dhyts","f.pile.html":"Ta <b>Dhyts</b> freayll dy chooilley nhee ta fieau ort, trooid dy chooilley phryjeck: fyssyn, reddyn dy hoiaghey, obbyr nagh vod agh dooinney y yannoo. Ta dty heshaght gra cre ta ny lurg as kys liurid ta eh goll dy ghoaill.","f.sleep.h":"Possanyn ta obbraghey choud as t'ou 'sy ruggyr","f.sleep.p":"Ta leeideilagh as possan jeh jaagenyn AI ec dy chooilley phryjeck. Screeu gaghlin er cart as ta'n possan doostey, jannoo yn obbyr, as cur eh back lesh kemmeeyn oddys dooinney skee leeideil.","f.tester.h":"Ta tester AI jeeaghyn ec toshiaght","f.tester.p":"Roish my jig red erbee dty hioree, ta tester geaishtagh ny kemmeeyn ayns coip jeh'n appey as soilshaghey cre honnick eh, lesh screenshot. Jeeagh er ny deaisht as gow rish ayns un chliklee.","f.proof.h":"Fys, cha nee gialdyn","f.proof.p":"Ta dy chooilley chur-trooid soilshaghey cre ta caghlaait: ny coadanyn, y diff, ny screenshots. Cha vel ymmyd dy hoshlit dy chooilley appey dy akin my ta eh jeant.","f.chat.h":"Loayr rish dty leeideilee","f.chat.p":"Rail goll rish Discord: un ikon son dy chooilley phryjeck, diamondyn ghoair son ny ta feme orrin. Cur screeuyn gys leeideilagh lesh smooinaght; ta eh cur eh ayns cartyn as plaan, lesh cliklee ✅ Go.","f.tidy.h":"Ta eh freayll eh hene aarloo","f.tidy.p":"Ta cartyn giarrey cheet cooidjagh ayns un, ta ennymyn ghoill er nyn gerraghey, as ta shilley tokenyn freayll yn coad caol. Ny sloo dy reddyn dy chlaghey, ny sloo dy smooinaghtyn.","f.private.h":"Lhiats, er dty chooid-earrooder","f.private.li1":"Ta'n bord roie er dty vashin hene as cha vel eh freggyrt agh dhyts.","f.private.li2":"Ta DMyn pryveyt eddyr pobble enmyssit veih kione gys kione.","f.private.li3":"Cha vel coontyn, cha vel trackeryn, cha vel cookies ayn.","f.lang.h":"Ayns dty chengey hene","f.lang.p":"Erskyn 120 chengey, veih Ollanish, Bretnish as Yapaanish gys pirat, Yoda as Klingon, lesh caghlaa tappee back gys Baarle son goan ny keirdey.","f.service.h":"Veih smooinaght gys service feer","f.service.p":"Hrog oo red ennagh lesh AI ta pobble nish jannoo ymmyd jeh? Cowr eh myr service as nee yn boayrd cooney lhiat dy reaghey eh dy mie: prowallyn uptime, duillag status phublick, incidents lesh coontey screeuit, caghlaaghyn ta feme er Go, coipyn-sauchys prowit dagh laa. Ta Cooney ynsaghey dagh kesmad dhyt myr t’ou goll.","msgr.h2":"AI-gile Messenger: dty possan ayns dty phoggaid","msgr.p1":"Loayr rish dty possan AI gyn y bord y osley. Loayr rish leeideilee dty phryjeckyn as rish dty charjyn, as jeeagh er kemmeeyn prowal cart as freggyr ad, ooilley veih dty fone.","msgr.p2":"Dy chur eh cooidjagh, scan coad QR er dty vord. Y chied cheayrt? Nee co-loayrtys demo caarjoil soilshaghey dhyt kys te goll.","msgr.when":"Android hoshiaght, eisht lhieggan eggey son fone as iPhone.","msgr.who":"Leeideilagh dty phryjeck","msgr.b1":"Ta'n caghlaa son y mod dorraghey aarloo. Vel oo laccal ny kemmeeyn prowal?","msgr.b2":"Ta, my sailt!","msgr.b3":"1. Foshil Soiaghyn. 2. Reih Dorraghey. Vel eh jeeaghyn kiart?","tl.aria":"Linney traa veih'n chied resooney gys y vapp-raad","tl.h2":"Veih'n chied resooney gys ny ta ry-heet","tl.lede":"Laghyn as tiaghyn firrinagh, ayns dty chroo-traa hene. Lurg jiu, te plaan, gyn laa erbee gialdit.","tl.today":"Jiu","tl.planned":"plaanit","tl.cards.one":"{n} chart","tl.cards.other":"{n} chart","join.h2":"Cum lhiat","join.lede":"Ta AI-gile ta troggit liorish dooinney quaagh lesh feasag, ta AuDHD echey as paart dy chaggaghyn rish slaynt e aigney, as liorish earroo vooar jeh jaagenyn foiljagh. Te pryveyt nish, ayns alpha dooint rish carryn. Vel oo gearree eh y hoiaghey tra vees eh foshlit?","join.btn":"Claare shilley","join.small":"Nee mayd screeu er-ash dhyts, cha nhee elley","footer.tag":"AI-gile. Cha vel trackeryn, cha vel cookies, cha vel caffee stand-up.","footer.licence":"Kied dy ghellal","footer.status":"Stayd","footer.privacy":"Ny freayll mayd","footer.thanks":"Eamyn lesh booise da ChilledChat","form.sending":"Gura cur…","form.failed":"Cha ren shen obbyr: gow dty hrial reesht ny s'anmey.","form.offline":"Cha dod mayd cosney AI-gile: gow dty hrial reesht ny s'anmey.","form.keep":"Cha nhee mayd ymmyd jeh shoh agh dy freggyrt dhyt, as eisht scryssee mayd ass eh. Cha vel trackeryn, cha vel cookies.","form.keepLink":"Ny freayll mayd","interest.title":"AI-gile: insh dou tra vees alpha foshlit","interest.description":"Faag dty phost-d dy chlashtyn tra vees alpha ny beta dooint AI-gile foshlit.","interest.h1":"🔔 Insh dou tra vees eh foshlit","interest.lede":"Ta AI-gile ayns roie-alpha dooint. Faag dty phost-d as nee mayd screeu un cheayrt, tra vees ynnyd dhyts.","interest.email":"Dty phost-d","interest.which":"Cre'n test?","interest.alpha":"Alpha dooint: toshiagh, garroo, ymmodee caghlaaghyn","interest.beta":"Beta: ny share, ny s'anmey","interest.both":"Y jees, quoi-erbee ver y chied chiaull","interest.submit":"Cur mee er y rolley","interest.thanks":"Gura mie ayd! Ta oo er y rolley.","licence.title":"AI-gile: kied dy ghellal","licence.description":"Vel oo goaill ymmyd jeh AI-gile ayns dty ghellal? Shirrey kied dy ghellal seyr.","licence.h1":"📜 Kied dy ghellal","licence.lede":"Vel oo goaill ymmyd jeh AI-gile ec obbyr? Insh dooin quoi oo as cre ta oo jannoo. My ta eh jannoo mie ennagh, ta'n kied seyr.","licence.company":"Co-heshaght","licence.website":"Ynnyd-eggey","licence.what":"Cre ta oo jannoo","licence.how":"Kys te cooney rish y theihll","licence.email":"Post-d","licence.submit":"Shirrey","licence.thanks":"Gura mie ayd! Freggyrt mayd liorish post-d.","status.title":"Stayd AI-gile","status.h1":"Stayd AI-gile","status.quiet":"Dy chooilley nhee kiune","status.intro":"Vel AI-gile gobbraghey nish? Ta'n duillag shoh jeeaghyn er yn ynnyd-eggey, rheynn ny buird, ny geamyn as y laadey neose dagh 5 minnid.","status.up":"Gobbraghey (dreggyr eh ayns {ms} ms)","status.slow":"Cha dreggyr eh yn shilley s'jerree, goaill trial reesht","status.down":"Neose: cha dreggyr eh ny daa hilley s'jerree","status.svc.web":"Ynnyd-eggey","status.svc.web.offers":"Yn ynnyd shoh: cre ta AI-gile, as y form son shilley","status.svc.boards":"Rheynn buird","status.svc.boards.offers":"Buird phobblagh, chaghteraghtyn eddyr caarjyn as cuirraghyn","status.svc.calls":"Geamyn","status.svc.calls.offers":"Coraa, feeshan as rheynn screen ayns AI-gile","status.svc.download":"Laadey neose","status.svc.download.offers":"Yn stoaliagh Windows as kianglaghyn cuirree","status.checking":"Shilley…","status.offline":"Cha dod mayd cosney shirveish y stayd nish (goaill trial reesht)","status.updated":"currit er y chooid {ago}","status.justNow":"nish dy jarroo","status.min":"{n} minnid er dy henney","status.hours":"{n} oor er dy henney","status.days":"{n} laa er dy henney","privacy.title":"AI-gile: ny freayll mayd","privacy.h1":"Ny freayll mayd","privacy.lede":"Yn aght giare: agh ny chur oo dooin, as cha nee son traa liauyr.","privacy.only":"Agh ny chur oo dooin: ny screeu oo ayns form, myr dty phost-d. Cha nhee elley mychione oo.","privacy.sealed":"Te sealit myr nagh vod yn shirveishagh ain lhaih eh: ayns dty vrawseyr roish my faagys eh (er brawseyr ny shinney, cha leah's roshys eh). Cha vod agh yn bord ain hene fosley eh.","privacy.server":"Te scryssit ass y shirveishagh cha leah's roshys eh yn bord ain. Red erbee ta foast ayn lurg 30 laa, te scryssit ass ayns aght erbee.","privacy.board":"Freayll mayd eh er y vord ain agh derrey nee mayd freggyrt dhyt, as eisht scryssee mayd ass eh ayns shen myrgeddin.","privacy.none":"Cha vel trackeryn, cha vel cookies, cha vel anallys.","privacy.local":"Ta dty hengey as dty reih soilshey ny dorraghey fuirraghtyn ayns dty vrawseyr hene. Cha vel ad rieau currit dooin.","privacy.ask":"Bare lhiat eh ve ersooyl ny s'leah? Freggyr yn post-d ain as abbyr shen.","live.h2":"Jeeagh er goll er ny hroggal, bio","live.caption":"Ta dagh cart foast: vees oo cummey yn obbyr, cha nee ny goan.","live.watching.one":"bio: {n} jeeaghyn","live.watching.other":"bio: {n} jeeaghyn","live.last.now":"Va'n cardey s'jerree scughit nish dy lhean","live.last.min.one":"Va'n cardey s'jerree scughit {n} minnid er dy henney","live.last.min.other":"Va'n cardey s'jerree scughit {n} minnid er dy henney","live.last.hour.one":"Va'n cardey s'jerree scughit {n} oor er dy henney","live.last.hour.other":"Va'n cardey s'jerree scughit {n} oor er dy henney","live.last.day.one":"Va'n cardey s'jerree scughit {n} laa er dy henney","live.last.day.other":"Va'n cardey s'jerree scughit {n} laa er dy henney","live.offline":"Ta'n clar bio goaill anmagh veg. Tar back dy gerrid.","live.cols":"Backlog|Dy yannoo|Ayns obbyr|Yn possan jeeaghyn|Dhyts dy testail|Son y possan|Jeant","pitch.words.two":"{n} fockle","pitch.words.few":"{n} fockle","pitch.letters.two":"{n} lettyr","pitch.letters.few":"{n} lettyr","pitch.chars.two":"{n} caractar","pitch.chars.few":"{n} caractar","count.line.html.two":"{n} chart er y bord nish","count.line.html.few":"{n} chart er y bord nish","tl.cards.two":"{n} chart","tl.cards.few":"{n} chart"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Currit-magh."]},{"n":2,"texts":["Kanban robotagh.","Jaagenyn, aarloo.","Smooinaghtyn, troggit."]},{"n":3,"texts":["Kanban son robots.","Smooinaghtyn dy ghoo.","Kanban jaagent, seyr."]},{"n":5,"texts":["Bord kanban rollit liorish jaagenyn.","Screeu cartyn. Troggee jaagenyn.","Seyr, logalagh, jeeaghit, red beg ommijagh."]},{"n":8,"texts":["Bord kanban seyr raad ta jaagenyn AI obbraghey.","Screeu smooinaght. Troggee jaagenyn eh. Ghow oo rish.","Agile son un dooinney as ymmodee robots foiljagh."]},{"n":13,"texts":["Bord kanban er dty chooid-earrooder raad ta jaagenyn AI goaill ny cartyn.","Screeu smooinaght. Troggee possan jaagenyn eh. Nee tester eh y yeeaghyn.","Seyr, cha vel coontyn ny trackeryn: bord, paartey dy robots, as oo hene er y chione."]},{"n":21,"texts":["Ta AI-gile bord kanban son obbraghey lesh jaagenyn coadaghey AI. Ta'd goaill ny cartyn; t'ou geaishtagh as goaill rish.","Ta leeideilagh as possan jeh jaagenyn AI ec dy chooilley phryjeck. Screeu gaghlin er cart erbee as ta'n possan goaill toshiaght dy obbraghey.","Bord dy-yannoo pearsoonagh, seyr, ta roie er dty chooid-earrooder hene. She robots ny obbraghee. She oo hene yn fer ta gra ta."]},{"n":34,"texts":["Ta oo cur smooinaghtyn er bord. Ta possan jeh jaagenyn AI cur ad ayns reddyn obbraghey, jeeaghyn ad, as cur ad back dhyts lesh kemmeeyn dy hoiaghey. Cha vel nhee erbee jeant derrey t'ou gra eh.","Ta AI-gile bord kanban troggit ec thie ec Rich lesh ymmodee cooney veih ny jaagenyn ta eh nish rolley. Te seyr, ta eh roie er dty chooid-earrooder, as te rannit rish carryn, cha nee creckit.","Smooinee er bord kanban cadjin, lesh colooyn veih Backlog gys Jeant, agh ta jaagenyn AI goaill ny cartyn. Ta'd cur lieh-lioar er cheayrt, fyssaghey tra t'ad fo-ghooinney, as ta'd fieau dy kinjagh er dty ghoo-ayrn."]},{"n":55,"texts":["Ta AI-gile bord kanban raad ta'n possan jeant jeh jaagenyn AI. Ta leeideilagh ec dy chooilley phryjeck ta plaanal yn obbyr as ynseyderyn ta troggal eh. Tra ta red aarloo, ta tester AI gerjagh eh as goaill screenshot, eisht ta eh cheet gys dty chrink. Gow rish eh, ny screeu gaghlin as nee ad jannoo eh reesht.","Haghyr eh myr raad un pherson dy yeeaghyn ymmodee shessanyn coadaghey AI ec un cheayrt, as dy-yannoo daaghey eh dy ve bord kiart. Ta eh roie er dty vashin, cha vel eh shirrey coontys, as cha vel trackeryn echey. Te seyr son carryn as pobble feaysagh. Te neu-hie neesht, shen-y-fa jean shilley rish gaaue as surprise ayns ynnydyn.","Shoh yn lane onneyr. Ta feme ort foast smooinaghtyn y ve ayd, as feme ort foast jeeaghyn ny toyrtyssyn. Ny ta AI-gile jannoo she dy chooilley nhee eddyr y daa: te freayll ny cartyn ayns oardagh, doostey yn jaagent kiart tra t'ou screeu gaghlin, soilshaghey dy kiart cre ta caghlaait, as freayll dy chooilley nhee ayns un chrink giarrey dhyts."]},{"n":89,"texts":["Ta AI-gile bord kanban seyr t'ou roie er dty chooid-earrooder hene. Ayns ynnyd pobble, ta possan jeh jaagenyn AI ec dy chooilley phryjeck: leeideilagh ta cur dty smooinaghtyn ayns cartyn as plaan, as ynseyderyn ta goaill ny cartyn ayns oardagh ard-phrimmys. Tra ta red troggit, ta tester AI geaishtagh ny kemmeeyn test as soilshaghey dhyts cre honnick eh. Eisht ta eh fieau ayns un chrink enmyssit Dhyts. T'ou goaill rish eh, ny screeu gaghlin as ta'n possan goaill trial elley. Cha vel nhee erbee cheet gys Jeant erbee dty heshaght.","Ta paartey dy reddyn nagh vod oo shilley rish. Ta shilley oie freayll y cholloon Dy yannoo lane choud as t'ou 'sy ruggyr, reih cartyn nagh vel feme ec ny freggyrt veih dyts. Ta earrooder token soilshaghey cre va ymmydit ec ny jaagenyn jiu as yn chemmeeys shoh, as ta No Token Mode gra roo scuirr dy chaiyn. Foddee oo screeu gys carryn, as ta screeuyn pryveyt enmyssit veih kione gys kione. Ta'n bord loayrt mychione 120 chengey, as Ollanish, Flemish, pirat as Klingon cooidjagh. Cha vel nhee jeu ayns jerrey cost er pene, as cha vel dooinney erbee shirrey dy chreck eh dhyts.","Ta AI-gile pryjeck beg, pearsoonagh, cha nee co-heshaght. V'eh dty ghraih Rich dy yannoo kiarail jeh ymmodee phryjeckyn coadaghey AI gyn dy hoshlit dy chooilley appey dy yeeaghyn orroo, myr shen hug eh hene as ny jaagenyn bord son shen, as eisht ghow ad ymmyd jeh'n bord dy hroggal ny va faagit. Te ayns roie-alpha dooint, shen dy ghra te goll er, dy mie, son dorrys dy charrey. Cha vel duillag brisht, cha vel screeuyn-naight, as cha vel plaan gaase. My ta eh jeeaghyn dy ve ymmydagh, foddee oo shirrey dy hoiaghey eh tra vees eh foshlit ny s'ooilley."]},{"n":144,"texts":["Ta AI-gile bord kanban son un dooinney as ymmodee jaagenyn AI. Te roie er dty chooid-earrooder hene as te dy-lhieggan seyr. T'ou cur pryjeckyn lesh, as ta leeideilagh as possan veg ec dy chooilley phryjeck. T'ou loayrt rish y leeideilagh, goll rish Discord, as taggloo mychione smooinaght; ta'n leeideilagh cur eh ayns cartyn as plaan, eisht fieau erriu dy hrimmey Go. Ta'n possan goll trooid ny cartyn ayns oardagh ard-phrimmys, lesh linney-currym aashagh jeant son ard-eie chengey. Roish my jig red erbee back dhyts, ta tester AI geaishtagh ny kemmeeyn ayns coip jeh'n appey as cur screenshot rish. Ta obbyr jeant cheet gys dty chrink lesh ny coadanyn caghlaait as y diff. T'ou goaill rish eh, ny faagail gaghlin as ta'n possan doostey as goaill trial reesht. Cha vod agh oo hene cart y hoiaghey gys Jeant.","Laa lesh AI-gile, kiart dy chooilley. Anmeeragh t'ou faagail paartey dy ghaghlinyn: ta'n cliklee shoh 'sy ynnyd cairal, lhisagh yn rolley shen ve currit ayns oardagh, vod mayd jannoo reihys dorraghey. T'ou goll dy heillagh. Ta ny jaagenyn lhaih ny gaghlinyn, jannoo ny caghlaaghyn, jeeaghyn ad as cur ad back dhyts. My ta Dy yannoo goll follym, ta shilley oie lhieeney eh veih'n backlog lesh cartyn nagh vel feme ec freggyrt veih dyts. Moghrey, ta un chrink giarrey ayn: daa ny three fyssyn as paartey dy reddyn dy hoiaghey, gagh un lesh kemmeeyn oddys dooinney cadley leeideil as screenshot jeh goll er. T'ou cliklee trooid, goaill rish ny mie as cur back ny vooarey. Ta earrooder token soilshaghey cre va ymmydit, as ta No Token Mode ayn son hiaghtynyn caol. Eisht t'ou goaill bee-moghrey, nagh vod ny jaagenyn cooney lesh foast.","Ec toshiaght, cre nagh nee AI-gile. Cha nee startup eh, cha vel eh son creck, as cha vel dooinney erbee cruinnaghey dty ghata. Te bord seyr ta roie er dty chooid-earrooder, gyn coontyn, gyn trackeryn as gyn cookies. Cre te: un ynnyd aarloo dy akin dy chooilley phryjeck coadaghey AI dy-cheilley, lesh possan jaagenyn jannoo ny cartyn as oo hene jannoo ny reihyn. Ta eh cur cartyn giarrey cooidjagh, kerraghey ennymyn ghoill, as freayll shilley er cre cha caol ta'n coad cummal. Ta eh loayrt mychione 120 chengey, veih Ollanish as Flemish gys pirat as Klingon. Foddee carryn screeu da cheilley, pryveyt as enmyssit. Hug Rich as ymmodee jaagenyn foiljagh eh seose, ymmydagh jeh eh hene sheean. Te ayns roie-alpha dooint, myr shen te garroo ayns ynnydyn. My ta eh jeeaghyn dy ve gaue, eam dy mie as foddee oo cheet stiagh moal."]}],"quips":{"1":"Un fockle. Dennal. Foddee dy chooid ro vooar.","3":"Three focklyn. Er-lhiam ny s'onneyr na ymmodee duillagyn bree.","8":"Hoght focklyn. Foast giarey na stand-up.","21":"She points skeealley ny lhiurideyn, my sailliu. Dy bragh.","55":"Queig as queig-jeig focklyn. Ve daa chart jeant choud as v'ou lhaih shen.","144":"Shen yn lhiurid hrooid. Cha vel 233 ayn. Ta ny jaagenyn er gheddyn dy cadley."}},"timeline":{"first-idea.name":"Yn chied smooinaght","first-idea.line":"Yn chied resooney, roish my row coad erbee ayn.","first-board.name":"Yn chied bord","first-board.line":"Bord ta jeeaghyn er e hroggal hene: cartyn, colooyn, tayrn as tilgey, pryjeckyn.","team-roles.name":"Possan as rolleyn","team-roles.line":"Pryfilyn jaagent, tempeljyn possan, ynnydyn as quoi ta jannoo cre.","install.name":"Soiaghey as cur-magh","install.line":"Zip oddys carrey y hoiaghey, nuaghey-hene, rheynnyn as shaghey back.","usage-saver.name":"Sauail ymmyd","usage-saver.line":"Mooadee cre ta roieyn costal, freayll y coad caol, sauail dty chordail.","friends.name":"Carryn as rannagh","friends.line":"DMyn pryveyt, relay enmyssit, cuirrey, rolleyn as pryjeckyn rannit.","languages.name":"Chengaghyn","languages.line":"Dy chooilley screeuyn screen ayns coadan chengey, lesh Ollanish as Flemish er toshiaght.","ai-tester.name":"Tester AI","ai-tester.line":"Ta tester jeeaghyn dy chooilley chur-trooid ec toshiaght as soilshaghey cre honnick eh.","website.name":"Yn ynnyd-eggey","website.line":"aigile.lol, y teaser as y linney-traa shoh.","streaming.name":"Resooney as streaming","streaming.line":"Discord, Twitch, OBS, reihys streamer, GIFs as emojis.","no-ai.name":"Cur-magh gyn AI","no-ai.line":"Bord son sleih ta coadaghey gyn AI, as bordyn poblagh.","night-watch.name":"Shilley oie","night-watch.line":"Ta fer-faghey as Scrum Mainshter freayll ny possanyn er yn obbyr choud as t'ou 'sy ruggyr.","p-more.name":"Dy chooilley nhee elley","p-more.line":"Smooinaghtyn sloo ta fieau foast er nyn gooyl.","p-android.name":"Fone as Android","p-android.line":"Cosney dty bord veih fone, eisht appey Android dooghyssagh.","p-release.name":"Alpha as ny s'anmey","p-release.line":"Alpha dooint, y ynnyd bio, eisht beta.","p-languages.name":"Ny sodjey chengaghyn","p-languages.line":"Erskyn keead chengey, as reihys immersion son ynseydee.","p-engines.name":"Ny sodjey ard-eaynyn AI","p-engines.line":"Reih Claude, Codex ny Gemini son dagh jaagent.","p-pro.name":"Cliaghtey pro","p-pro.line":"Lioaryn ghaue, dorrysyn merge, cartyn tarmaynyn as raillyn-coadey.","p-self.name":"Tayrn kiarail ort hene","p-self.line":"Reihys skee, cooinaghtynyn hene-kiarail as 4:20.","p-servers.name":"Servaneyderyn as scale","p-servers.line":"Soiaghyn server cooidjagh, rolleyn as plaanal son gaase.","p-livestream.name":"Reddyn streaming elley","p-livestream.line":"Chat Twitch, emojis custom as shilley bio poblagh."},"words":{"button":"📖 Goan ny keirdey","h":"📖 Goan mynit","intro":"Ny goan ver oo er ayns AI-gile, ayns goan soilshey: troggal eh, caghlaa eh dy sauchey, freayll eh goll son y pobble ta jannoo ymmyd jeh, as gobbraghey myr possan lesh AI.","search":"Shirrey goan…","none":"Cha vel goan cooidsaghey shen.","close":"Dooney","count":{"one":"{count} goo","other":"{count} goan"},"groups":[{"id":"build","name":"🛠️ Troggal eh"},{"id":"change","name":"🔀 Caghlaa eh dy sauchey"},{"id":"run","name":"🛎️ Reaghey service"},{"id":"team","name":"🤝 Gobbraghey myr possan (as lesh AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Pillagh coad y phryjeck as e hennaghys slane jeh commits, dy cadjin freayllit er GitHub myrgeddin.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linney scarrit jeh obbyr ayns y choad, dy vod caghlaaghyn ve jeant gyn tayrn er y lhieggan s'mie.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Dealbh sauailt jeh'n coad, lesh cooish ghiare jeh cre ren caghlaa. Foddee oo goll er ash gys unnane dy kinjagh.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Cur dealbyn sauailt (commits) veih'n co-earrooder shoh gys GitHub, dy vel ad cooillit as rheynnit."},{"id":"merge","g":"build","word":"Merge","text":"Cur caghlaaghyn branch gys y lhieggan s'mie reesht."},{"id":"pr","g":"build","word":"Pull request","text":"Fenney dy vel caghlaaghyn branch jeeaghit as cur gys y lhieggan s'mie.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Glenney y choad gyn caghlaa cre ta eh jannoo: coadanyn s'veggey, ennymyn s'soilshey, sloo ashoonaghey."},{"id":"bug","g":"build","word":"Bug","text":"Red nagh vel gobbraghey myr lhisagh eh.","also":["bugs"]},{"id":"test","g":"build","word":"Prowal","text":"Prowal obbyr jeant dy yeeaghyn dy vel eh jannoo cre va fenneyt, roish y ghymmyrkey.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Giarrey son quality assurance: ny prowallyn hene-obbragh ta roie roish ta red erbee goll bio. Tra ta QA jiarg, ta red ennagh er failleil, as cha vod eh goll bio derrey ta shen jeshit.","also":["prowallyn feeuid","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Cur lhieggan vree bio, y.e. er servaneyder raad ta pobble ymmyd jeh."},{"id":"release","g":"change","word":"Release","text":"Bundel enmyssit jeh obbyr jeant ta goll bio cooidjagh, lesh notaghyn giare er ny va caghlaait. Ta 🚀 Releases screeu ny notaghyn veih ny carteyn jeant.","also":["releases","lhieggan"]},{"id":"rollback","g":"change","word":"Roll back","text":"Goll er ash gys y lhieggan s’jerree va gobbraghey tra ta lhieggan noa jannoo trubbyl. Ayns AI-gile, t’eh jannoo rolley-prowal jeh ny kesmadyn dy chur er ash, screeuit er dagh caghlaa.","also":["rollback","roll-back","cur er ash"]},{"id":"live","g":"change","word":"Bio","text":"Y lhieggan feer ta pobble jannoo ymmyd jeh, cha nee coip son prowal reddyn. Ta ymmydeyryn gra production rish myrgeddin.","also":["production","live"],"noTip":1},{"id":"change","g":"change","word":"Caghlaa","text":"Caghlaa kiartit er red ennagh ta pobble croghey er, screeuit sheese hoshiaght: cre, cre’n fa, y danjeyr, cuin, as kys dy chur er ash eh. Toshee fer lesh 🔀 Troggal caghlaa.","also":["caghlaaghyn","change request"],"noTip":1},{"id":"risk","g":"change","word":"Danjeyr","text":"Red ennagh oddagh goll rish shaghryn, lesh scoar er cho lhisagh eh taghyrt as cho olk as veagh eh. Ta ⚠️ Kione-chiaraillyn freayll ad ayns un rolley, y scoar syrjey hoshiaght, dagh fer lesh date dy yeeaghyn reesht.","also":["danjeyryn","kione-chiarail","risk register"]},{"id":"chgwin","g":"change","word":"Finnag caghlaa","text":"Ny traaghyn tra oddys caghlaaghyn goll bio, myr fastyr Jemayrt quiee. Mooie jeh finnag cha nod cart caghlaa ve jeant, mannagh nee eigin t’ayn.","also":["finnagyn caghlaa","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Vot tappee roish ta caghlaa goll bio: ta dagh peiagh ta feme echey gymmyrkey gra Go ny No go. Cha jed eh er y hoshiaght agh tra t’ad ooilley coardail.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Gymmyrkagh","text":"Fieau son “ta” roish ta’n obbyr toshiaght. Ta cart ta carrey troggal, ny caghlaa, fieau ayns ✅ Gymmyrkaghyn derrey t’ou gymmyrkey ny obbal eh.","also":["gymmyrkaghyn","approval"]},{"id":"quiettime","g":"change","word":"Traa quiee","text":"Tammylt dy hraa, myr stream, demo ny yn oie, tra nagh vel red erbee goll bio. Ta ny possanyn freayll orrin gobbraghey as prowal, agh ta goll bio fieau derrey t’eh harrish. Ayns boayllyn elley t’eh enmyssit change freeze.","also":["traaghyn quiee","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Red ennagh hrog oo ta pobble croghey er, myr ynnyd-eggey ny app, kiarail jeh dy vel eh freayll er gobbraghey. Cur kaart er “Ta’n pryjeck shoh service” as insh cre t’eh chebbal, quoi ta jannoo ymmyd jeh as quoi ta on-call.","also":["services"]},{"id":"uptime","g":"run","word":"Prowal uptime","text":"Prowal hene-obbragh, dagh shiartanse dy vinnidyn, dy vel dty service foast freggyrt. My t’eh failleil keayrtyn ny lurg y cheilley, ta AI-gile fosley cart incident er e hon hene.","also":["uptime","prowallyn uptime"]},{"id":"statuspage","g":"run","word":"Duillag status","text":"Duillag phublick ta soilshaghey vel service gobbraghey (glass, oranse ny jiarg) lesh y naight s’noa, son dy vod y pobble ta jannoo ymmyd jeh jeeaghyn ayns ynnyd dy vriaght.","also":["duillagyn status","status page"]},{"id":"incident","g":"run","word":"Incident","text":"Red ennagh ta brisht son y pobble ta jannoo ymmyd jeh nish, myr yn ynnyd-eggey ve sheese. Ta cart 🔥 incident lheimyragh roish y tidey: t’eh y chied red dy gheddyn eh gobbraghey reesht.","also":["incidents","taghyrt"]},{"id":"major","g":"run","word":"Incident mooar","text":"Incident feer vooar: ymmodee pobble jeh, ny argid ny fysseree ayns danjeyr. Ta un chramman cur dagh possan er (swarm), doostey quoi erbee ta on-call as briaght son naight status dagh 30 minnid.","also":["incidents mooarey","toshiaght mooar","major incident"]},{"id":"oncall","g":"run","word":"On-call","text":"Ve yn fer ta freggyrt tra ta red ennagh brishey, eer ec yn oie. Ta oltey possan on-call ec dagh service ta doostit hoshiaght son ny incidents echey.","also":["on call"]},{"id":"replyby","g":"run","word":"Traa freggyrt","text":"Cre cho liauyr as oddys cart fieau son y chied freggyrt, myr shampleyr oor son incident. Lurg shen ta clag jiarg echey, son nagh bee red erbee jarroodit dy kiune. T’eh enmyssit response target myrgeddin.","also":["traaghyn freggyrt","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Jeeagh giare er ash lurg incident: cre haghyr, cre ren cooney as cre lhisagh caghlaa, gyn cur y oghsan er peiagh erbee. Cha nod incident ve dooint fegooish fer.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Doilleeid","text":"Y chooish follit cooyl jeh un incident ny ny smoo. Ta cart 🧩 doilleeid chaglym incidents ta cheet er ash dy kinjagh, son dy bee y chooish feddynit as jeshit son dy bragh.","also":["doilleeidyn","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Bun-chooish","text":"Yn oyr feer ren red ennagh brishey, cha nee agh ny honnick oo goll rish shaghryn. Jesh y vun-chooish as cha jig yn incident er ash.","also":["bun-chooishyn","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"Aght dy reayll reddyn gobbraghey derrey ta’n jesheenys feer aarloo, myr cur red ennagh er reesht tra t’eh lhiantyn. T’eh screeuit er y chart doilleeid son nagh bee orrin peiagh erbee dy obbraghey magh eh reesht.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Jant enney","text":"Doilleeid ta’n chooish eck toiggit as ta workaround eck, agh nagh vel jeshit foast. Ta 🧩 Ny jantyn enney cur rolley jeu, son dy jean dy chooilley pheiagh ymmyd jeh’n workaround ayns ynnyd dy chleiy reesht.","also":["jantyn enney","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Saraghyn kesmad er kesmad son jeshaghey sorch trubbyl enney, son dy bee eh jeant yn aght cheddin, dy tappee, dagh keayrt. Lurg incident mooar, foddee yn possan fer y chur seose dhyt son OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Coip-sauchys","text":"Coip sauailt jeh dty fysseree veih roie, dy huittym er ash er my ta red ennagh caillit ny jeeghit. Ta AI-gile jannoo coip-sauchys jeh dty voardyn dagh laa.","also":["coipyn-sauchys","backup","backups"]},{"id":"restore","g":"run","word":"Aahoiaghey","text":"Cur fysseree er ash veih coip-sauchys. Cha nel coip-sauchys coontey dy feer derrey ta fys ayd dy vod eh ve aahoit, myr shen t’eh feeu prowal eh nish as reesht.","also":["aahoit","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Smooinaghtyn as obbyr nagh vel planit foddey. Cha vel red erbee ayns shen gobbraghey er derrey t'eh gleashtyn gys Dy yannoo."},{"id":"sprint","g":"team","word":"Sprint","text":"Traa giare jeh obbyr (dy cadjin shiaghtin ny daa) lesh set cordit jeh carteyn dy yannoo.","also":["sprints"]},{"id":"standup","g":"team","word":"Tashtey shassoo","text":"Jeeaghyn tappee: cre ren dy chooilley fer-lhiasee, cre nee eh ec heet, as cre ta e lhiettal.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Bord lesh colbaghyn (Dy yannoo, Ayns obbyr, Jeant) raad ta carteyn goll veih çheerey gys yesh myr ta obbyr tashtey."},{"id":"wip","g":"team","word":"Oardagh WIP","text":"Obbyr ayns obbyr: y keim smoo jeh carteyn lhisagh colbagh ve ayn, dy vel y possan jeantagh reddyn roish toshiaghtyn smoo.","also":["WIP"]},{"id":"dod","g":"team","word":"Mychione Jeant","text":"Rolley-prowal giare y phossan er cre ta “jeant” cur bun, myr prowit as mynit, roish ta cart currit dhyt. Ta’n lhiannoo-daa echey, Mychione Aarloo, gra cuin ta cart soilshey dy liooar dy hoshiaght.","also":["Definition of Done","Mychione Aarloo","Definition of Ready"]},{"id":"testpile","g":"team","word":"Carn prowal","text":"Ny carteyn jeant ta fieau ort dy phrowal, fer lurg fer. Gymmyrkey fer ny cur er ash eh lesh note, as ta’n nah fer cheet seose.","also":["carnyn prowal","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Jeeagh er ash er kys ta’n possan gobbraghey, dy choardail er un red dy yannoo ny share. Ayns AI-gile, ta retro cur caghlaa roish er aghtyn-obbyr y phossan, as t’ou gra Go ny Cha nee nish.","also":["retros","retrospective"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Jees elley dy hooillyn: ta AI elley prowal obbyr dagh cart roish t’eh roshtyn ort, son dy jig ny sloo dy hranlaasyn trooid.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Dy chooilley laue er y dekk: ta dagh possan faagail obbyr elley dy chooney lesh un phryjeck jeeragh derrey t’eh reaghit. Ta pryjeckyn elley fieau ’sy traa cheddin.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Yn fer ta freayll yn obbyr roie: t’eh fakin carteyn lhiantyn, greinnaghey ny possanyn as cur ayns cooinaghtyn dhyt cre ta fieau. Ayns AI-gile, ta’n Leeideilagh Scrum Mainshter jannoo shoh ayns dy chooilley phryjeck.","also":["Leeideilagh Scrum Mainshter","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Jaagent","text":"AI ta gobbraghey er-hene er obbyr: lhaih y choad, jannoo caghlaaghyn, roie jeeaghyn, as cur fys er ash.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Yn unnaid ta ymmyd AI earroo ayn: mysh paart ynnydyn jeh teks lhaihit ny scruit. Sloo tokens, smoo jeh dty phlan faagit.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Harey veg ta roie hene ec traa soit, y.e. tra ta shesheen AI toshiaghtyn, dy vel y possan clashtyn dty ghaghlinyn.","also":["hooks"]}]}};
